// Identify inactive clients
const clients = $node["Google Sheets - Get All Clients"].json;
const sessions = $node["Google Sheets - Get Session History"].json;
const reengagements = $node["Google Sheets - Get Reengagement History"].json;

// Current date for calculations
const now = new Date();

// Create a map of client IDs to their last session date
const lastSessionMap = new Map();
sessions.forEach(session => {
  if (session.client_id && session.session_date) {
    const sessionDate = new Date(session.session_date);
    if (!lastSessionMap.has(session.client_id) || 
        sessionDate > new Date(lastSessionMap.get(session.client_id).date)) {
      lastSessionMap.set(session.client_id, {
        date: session.session_date,
        status: session.status
      });
    }
  }
});

// Create a map of client IDs to their last reengagement date
const lastReengagementMap = new Map();
reengagements.forEach(reengagement => {
  if (reengagement.client_id && reengagement.date) {
    const reengagementDate = new Date(reengagement.date);
    if (!lastReengagementMap.has(reengagement.client_id) || 
        reengagementDate > new Date(lastReengagementMap.get(reengagement.client_id).date)) {
      lastReengagementMap.set(reengagement.client_id, {
        date: reengagement.date,
        type: reengagement.type
      });
    }
  }
});

// Find inactive clients
const inactiveClients = [];
clients.forEach(client => {
  // Skip clients with inactive status
  if (client.status && client.status.toLowerCase() === 'inactive') {
    return;
  }

  // Skip clients who have unsubscribed
  if (client.status && client.status.toLowerCase() === 'unsubscribed') {
    return;
  }

  const clientId = client.id || client.client_id;
  if (!clientId) return;

  // Check if client has had a session
  if (lastSessionMap.has(clientId)) {
    const lastSession = lastSessionMap.get(clientId);
    const lastSessionDate = new Date(lastSession.date);
    const daysSinceLastSession = Math.floor((now - lastSessionDate) / (1000 * 60 * 60 * 24));

    // Check if client has had a reengagement attempt
    let daysSinceLastReengagement = 999; // Default high value if no reengagement
    if (lastReengagementMap.has(clientId)) {
      const lastReengagement = lastReengagementMap.get(clientId);
      const lastReengagementDate = new Date(lastReengagement.date);
      daysSinceLastReengagement = Math.floor((now - lastReengagementDate) / (1000 * 60 * 60 * 24));
    }

    // Determine inactivity level
    let inactivityLevel = '';
    if (daysSinceLastSession >= 90) {
      inactivityLevel = 'high';
    } else if (daysSinceLastSession >= 60) {
      inactivityLevel = 'medium';
    } else if (daysSinceLastSession >= 30) {
      inactivityLevel = 'low';
    }

    // Add to inactive clients if inactive and no recent reengagement
    if (inactivityLevel && daysSinceLastReengagement >= 14) {
      inactiveClients.push({
        clientId,
        firstName: client.first_name || client.firstName || '',
        lastName: client.last_name || client.lastName || '',
        email: client.email || '',
        phone: client.phone || '',
        coachingType: client.coaching_type || client.coachingType || 'General',
        sessionCount: parseInt(client.session_count || client.sessionCount || 0),
        lastSessionDate: lastSession.date,
        daysSinceLastSession,
        inactivityLevel,
        lastReengagementDate: lastReengagementMap.has(clientId) ? lastReengagementMap.get(clientId).date : null,
        daysSinceLastReengagement
      });
    }
  } else {
    // Client has never had a session - check if they're a new client
    const createdDate = client.created_date || client.createdDate;
    if (createdDate) {
      const clientCreatedDate = new Date(createdDate);
      const daysSinceCreation = Math.floor((now - clientCreatedDate) / (1000 * 60 * 60 * 24));

      // If client was created more than 14 days ago but has no sessions
      if (daysSinceCreation >= 14) {
        inactiveClients.push({
          clientId,
          firstName: client.first_name || client.firstName || '',
          lastName: client.last_name || client.lastName || '',
          email: client.email || '',
          phone: client.phone || '',
          coachingType: client.coaching_type || client.coachingType || 'General',
          sessionCount: 0,
          lastSessionDate: null,
          daysSinceLastSession: null,
          inactivityLevel: 'new-inactive',
          lastReengagementDate: lastReengagementMap.has(clientId) ? lastReengagementMap.get(clientId).date : null,
          daysSinceLastReengagement: lastReengagementMap.has(clientId) ? 
            Math.floor((now - new Date(lastReengagementMap.get(clientId).date)) / (1000 * 60 * 60 * 24)) : 999
        });
      }
    }
  }
});

return {
  totalInactiveClients: inactiveClients.length,
  inactiveClients
};

// Segment inactive clients by inactivity level
const inactiveClients = $node["Code - Identify Inactive Clients"].json.inactiveClients;

// Create segments
const highInactivity = inactiveClients.filter(client => client.inactivityLevel === 'high');
const mediumInactivity = inactiveClients.filter(client => client.inactivityLevel === 'medium');
const lowInactivity = inactiveClients.filter(client => client.inactivityLevel === 'low');
const newInactive = inactiveClients.filter(client => client.inactivityLevel === 'new-inactive');

return {
  highInactivity,
  mediumInactivity,
  lowInactivity,
  newInactive
};

// Process high inactivity clients
const highInactivityClients = $node["Code - Segment Inactive Clients"].json.highInactivity;
const currentIndex = $input.item.index;

if (currentIndex < highInactivityClients.length) {
  return {
    ...highInactivityClients[currentIndex],
    segmentType: 'high'
  };
} else {
  return {};
}

// Process medium inactivity clients
const mediumInactivityClients = $node["Code - Segment Inactive Clients"].json.mediumInactivity;
const currentIndex = $input.item.index;

if (currentIndex < mediumInactivityClients.length) {
  return {
    ...mediumInactivityClients[currentIndex],
    segmentType: 'medium'
  };
} else {
  return {};
}

// Process low inactivity clients
const lowInactivityClients = $node["Code - Segment Inactive Clients"].json.lowInactivity;
const currentIndex = $input.item.index;

if (currentIndex < lowInactivityClients.length) {
  return {
    ...lowInactivityClients[currentIndex],
    segmentType: 'low'
  };
} else {
  return {};
}

// Process new inactive clients
const newInactiveClients = $node["Code - Segment Inactive Clients"].json.newInactive;
const currentIndex = $input.item.index;

if (currentIndex < newInactiveClients.length) {
  return {
    ...newInactiveClients[currentIndex],
    segmentType: 'new-inactive'
  };
} else {
  return {};
}

